functions._requires_compatibility_execution:
def _requires_compatibility_execution(
        window: Window,
        known: AgentRunRecord | None,
        manifest: dict[str, Any] | None,
        groups: list[RequestInteractionDataModel],
    ) -> bool:
        if env_bool("MOCK_LLM_RESPONSE", default=False):
            if known is not None:
                # A mode toggle must not replace durable real work with fake
                # results, fabricate source coverage, or refund its quota.
                raise ExtractionInputIntegrityError(
                    "Mock mode cannot replace an existing extraction agent run"
                )
            # Simulations have no provider input to budget. Keep their established
            # mock extraction/persistence behavior without admitting a protocol.
            return True
        if any(
            item.interacted_image_url or item.image_encoding
            for group in groups
            for item in group.interactions
        ):
            if manifest is not None:
                raise ExtractionInputIntegrityError(
                    "Admitted textual extraction cannot consume image evidence"
                )
            # Preserve the established multimodal prompt and evidence contract.
            # Text-only span witnesses cannot prove facts learned from images.
            return True
        # Completed marker-free plans keep their original persistence adapter.
        if manifest is None and window.outcome is not None:
            return True
        # Marker-free parents retain their original continuation/publication
        # adapter, including committed output. Never re-admit historical work.
        if known is not None and manifest is None:
            if known.status == AgentRunStatus.FAILED and known.committed_output is None:
                raise ExtractionInputIntegrityError(
                    "Failed legacy extraction needs explicit recovery; historical quota is unknown"
                )
            return True
        return False

functions._prepare_coordinator_sources:
def _prepare_coordinator_sources(
        groups: list[RequestInteractionDataModel],
        user_id: str,
        known: AgentRunRecord | None,
        manifest: dict[str, Any] | None,
    ) -> tuple[PreparedExtractionInput, int, int]:
        # Freeze this geometry before any provider work. Existing checkpoints
        # retain their original partition and cannot reclaim consumed slots.
        chunk_tokens = manifest.get("input_chunk_tokens", 8192) if manifest else 10000
        if type(chunk_tokens) is not int or chunk_tokens not in {8192, 10000, 20000}:
            raise ExtractionInputIntegrityError("Extraction partition changed")
        preparation_version = manifest.get("preparation_version", 1) if manifest else 3
        if type(preparation_version) is not int or preparation_version not in {1, 2, 3}:
            raise ExtractionInputIntegrityError(
                "Unknown extraction preparation version"
            )
        if known is None:
            prepared, chunk_tokens = prepare_initial_extraction_input(
                groups, user_id=user_id
            )
        else:
            prepared = prepare_extraction_input(
                groups,
                user_id=user_id,
                chunk_tokens=chunk_tokens,
                require_overlap=preparation_version >= 2,
                include_request_source=preparation_version == 3,
            )
        return prepared, chunk_tokens, preparation_version

functions._overflow_manifest:
def _overflow_manifest(known: AgentRunRecord | None) -> dict[str, Any] | None:
        if known is None or "overflow" not in known.generation_request_snapshot:
            return None
        # A damaged protocol marker is still protocol work. Never adopt it
        # as legacy work or replace its durable attempt journal.
        try:
            return validate_extraction_overflow_manifest(
                known.generation_request_snapshot["overflow"]
            )
        except OverflowCheckpointConflictError as exc:
            raise ExtractionInputIntegrityError(str(exc)) from exc

functions.from_payload:
def from_payload(
        cls, run: AgentRunRecord, data: Any
    ) -> "SavedPublicationPreparation":
        if not isinstance(data, dict) or set(data) != {
            "version",
            "output_id",
            "output_digest",
            "kind",
            "write_plan",
            "history_inputs",
            "bookmark",
        }:
            raise ExtractionInputIntegrityError("Saved publication preparation invalid")
        output = run.committed_output
        if not isinstance(output, dict):
            raise ExtractionInputIntegrityError("Preparation requires retained output")
        if (
            type(data["version"]) is not int
            or data["version"] != 1
            or data["output_id"]
            != require_output_id(output.get("publication", {}).get("id"))
            or data["output_digest"] != build_scope_hash(output)
            or data["kind"] != run.binding.extractor_kind
        ):
            raise ExtractionInputIntegrityError(
                "Saved publication preparation binding changed"
            )
        try:
            history = history_from_output(
                {"publication": {"history_inputs": data["history_inputs"]}}
            )
            plan = decode_write_plan(data["write_plan"], run.binding.extractor_kind)
            bookmark = _require_bookmark(run, data["bookmark"])
            if bookmark is not None and bookmark != bookmark_from_output(run):
                raise ValueError("Prepared bookmark changed its original position")
            if plan is not None:
                rows = (
                    plan.new_profiles
                    if isinstance(plan, ProfileWritePlan)
                    else plan.new_playbooks
                )
                if (
                    plan.request_id != run.binding.request_id
                    or isinstance(plan, ProfileWritePlan)
                    and plan.user_id != run.binding.user_id
                    or any(row.user_id != run.binding.user_id for row in rows)
                ):
                    raise ValueError("Publication subjects changed")
        except (ValueError, TypeError, KeyError, AttributeError) as exc:
            raise ExtractionInputIntegrityError(
                "Saved publication preparation invalid"
            ) from exc
        return cls(plan, history, bookmark)

